using System.Globalization;
using System.Text;

namespace TreeSpitter.Grammars;

/// <summary>
/// Writes a <see cref="Grammar"/> with the format of the <c>grammar.json</c> files generated by tree-sitter.
/// </summary>
internal sealed class GrammarJsonWriter
{
    private readonly StringBuilder _builder = new();
    private readonly bool _indented;
    private int _depth;

    private GrammarJsonWriter(bool indented)
    {
        _indented = indented;
    }

    public static string Write(Grammar grammar, bool indented)
    {
        var writer = new GrammarJsonWriter(indented);
        writer.WriteGrammar(grammar);
        return writer._builder.ToString();
    }

    private void WriteGrammar(Grammar grammar)
    {
        BeginObject();
        Property("$schema");
        String("https://tree-sitter.github.io/tree-sitter/assets/schemas/grammar.schema.json");
        Property("name");
        String(grammar.Name);

        if (grammar.Inherits is not null)
        {
            Property("inherits");
            String(grammar.Inherits);
        }

        if (grammar.Word is not null)
        {
            Property("word");
            String(grammar.Word);
        }

        Property("rules");
        BeginObject();
        foreach (var rule in grammar.Rules)
        {
            Property(rule.Name);
            WriteRule(rule.Rule);
        }

        EndObject();

        Property("extras");
        WriteRules(grammar.Extras);

        Property("conflicts");
        BeginArray();
        foreach (var conflict in grammar.Conflicts)
        {
            Separator();
            WriteStrings(conflict);
        }

        EndArray();

        Property("precedences");
        BeginArray();
        foreach (var list in grammar.Precedences)
        {
            Separator();
            WriteRules(list);
        }

        EndArray();

        Property("externals");
        WriteRules(grammar.Externals);

        Property("inline");
        WriteStrings(grammar.Inline);

        Property("supertypes");
        WriteStrings(grammar.Supertypes);

        Property("reserved");
        BeginObject();
        foreach (var set in grammar.Reserved)
        {
            Property(set.Name);
            WriteRules(set.Rules);
        }

        EndObject();

        EndObject();
    }

    private void WriteRules(IReadOnlyList<Rule> rules)
    {
        BeginArray();
        foreach (var rule in rules)
        {
            Separator();
            WriteRule(rule);
        }

        EndArray();
    }

    private void WriteStrings(IReadOnlyList<string> values)
    {
        BeginArray();
        foreach (var value in values)
        {
            Separator();
            String(value);
        }

        EndArray();
    }

    private void WriteRule(Rule rule)
    {
        BeginObject();
        Property("type");
        String(TypeName(rule));

        switch (rule)
        {
            case StringRule s:
                Property("value");
                String(s.Value);
                break;
            case PatternRule p:
                Property("value");
                String(p.Value);
                if (!string.IsNullOrEmpty(p.Flags))
                {
                    Property("flags");
                    String(p.Flags);
                }

                break;
            case SymbolRule s:
                Property("name");
                String(s.Name);
                break;
            case SeqRule s:
                Property("members");
                WriteRules(s.Members);
                break;
            case ChoiceRule c:
                Property("members");
                WriteRules(c.Members);
                break;
            case RepeatRule r:
                Property("content");
                WriteRule(r.Content);
                break;
            case Repeat1Rule r:
                Property("content");
                WriteRule(r.Content);
                break;
            case PrecRule p:
                Property("value");
                if (p.Value.Name is { } name)
                {
                    String(name);
                }
                else
                {
                    _builder.Append(p.Value.Number.ToString(CultureInfo.InvariantCulture));
                }

                Property("content");
                WriteRule(p.Content);
                break;
            case TokenRule t:
                Property("content");
                WriteRule(t.Content);
                break;
            case AliasRule a:
                Property("content");
                WriteRule(a.Content);
                Property("named");
                _builder.Append(a.Named ? "true" : "false");
                Property("value");
                String(a.Value);
                break;
            case FieldRule f:
                Property("name");
                String(f.Name);
                Property("content");
                WriteRule(f.Content);
                break;
            case ReservedRule r:
                Property("content");
                WriteRule(r.Content);
                Property("context_name");
                String(r.ContextName);
                break;
        }

        EndObject();
    }

    internal static string TypeName(Rule rule) => rule.Kind switch
    {
        RuleKind.Blank => "BLANK",
        RuleKind.Eof => "EOF",
        RuleKind.String => "STRING",
        RuleKind.Pattern => "PATTERN",
        RuleKind.Symbol => "SYMBOL",
        RuleKind.Seq => "SEQ",
        RuleKind.Choice => "CHOICE",
        RuleKind.Repeat => "REPEAT",
        RuleKind.Repeat1 => "REPEAT1",
        RuleKind.Prec => "PREC",
        RuleKind.PrecLeft => "PREC_LEFT",
        RuleKind.PrecRight => "PREC_RIGHT",
        RuleKind.PrecDynamic => "PREC_DYNAMIC",
        RuleKind.Token => "TOKEN",
        RuleKind.ImmediateToken => "IMMEDIATE_TOKEN",
        RuleKind.Alias => "ALIAS",
        RuleKind.Field => "FIELD",
        RuleKind.Reserved => "RESERVED",
        _ => rule.Kind.ToString().ToUpperInvariant(),
    };

    // Each container tracks whether it already has an item, to emit the commas.
    private readonly Stack<bool> _hasItems = new();

    private void BeginObject()
    {
        _builder.Append('{');
        _hasItems.Push(false);
        _depth++;
    }

    private void EndObject()
    {
        _depth--;
        if (_hasItems.Pop())
        {
            NewLine();
        }

        _builder.Append('}');
    }

    private void BeginArray()
    {
        _builder.Append('[');
        _hasItems.Push(false);
        _depth++;
    }

    private void EndArray()
    {
        _depth--;
        if (_hasItems.Pop())
        {
            NewLine();
        }

        _builder.Append(']');
    }

    private void Separator()
    {
        if (_hasItems.Peek())
        {
            _builder.Append(',');
        }
        else
        {
            _hasItems.Pop();
            _hasItems.Push(true);
        }

        NewLine();
    }

    private void Property(string name)
    {
        Separator();
        String(name);
        _builder.Append(_indented ? ": " : ":");
    }

    private void NewLine()
    {
        if (_indented)
        {
            _builder.Append('\n').Append(' ', _depth * 2);
        }
    }

    private void String(string value)
    {
        _builder.Append('"');
        foreach (var c in value)
        {
            switch (c)
            {
                case '"':
                    _builder.Append("\\\"");
                    break;
                case '\\':
                    _builder.Append("\\\\");
                    break;
                case '\n':
                    _builder.Append("\\n");
                    break;
                case '\r':
                    _builder.Append("\\r");
                    break;
                case '\t':
                    _builder.Append("\\t");
                    break;
                case '\b':
                    _builder.Append("\\b");
                    break;
                case '\f':
                    _builder.Append("\\f");
                    break;
                default:
                    if (c < 0x20)
                    {
                        _builder.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    }
                    else
                    {
                        _builder.Append(c);
                    }

                    break;
            }
        }

        _builder.Append('"');
    }
}
